import { useState } from 'react';
import { ProfileHeader } from './ProfileHeader';
import { ProfileStats } from './ProfileStats';
import { ActivityFeed } from './ActivityFeed';
import { ProfileForm } from './ProfileForm';

export function ProfilePage() {
  const [activeTab, setActiveTab] = useState<'overview' | 'edit'>('overview');

  return (
    <div className="min-h-screen bg-slate-50 font-sans">
      <div className="max-w-4xl mx-auto px-4 py-8">
        <ProfileHeader onEdit={() => setActiveTab(t => t === 'overview' ? 'edit' : 'overview')} isEditing={activeTab === 'edit'} />

        <div className="mt-6 flex gap-2 border-b border-slate-200">
          {(['overview', 'edit'] as const).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 text-sm font-medium capitalize transition-colors border-b-2 -mb-px ${
                activeTab === tab
                  ? 'border-violet-600 text-violet-700'
                  : 'border-transparent text-slate-500 hover:text-slate-700'
              }`}
            >
              {tab === 'edit' ? 'Edit profile' : 'Overview'}
            </button>
          ))}
        </div>

        <div className="mt-6">
          {activeTab === 'overview' ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-2 space-y-6">
                <ProfileStats />
                <ActivityFeed />
              </div>
              <div className="space-y-4">
                <div className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm">
                  <h3 className="font-semibold text-slate-800 mb-3">About</h3>
                  <p className="text-sm text-slate-500 leading-relaxed">Senior product designer passionate about crafting elegant, accessible interfaces. 8 years in the industry.</p>
                  <div className="mt-4 space-y-2 text-sm text-slate-500">
                    <div className="flex items-center gap-2">🌍 San Francisco, CA</div>
                    <div className="flex items-center gap-2">🔗 acme.design/alice</div>
                    <div className="flex items-center gap-2">📅 Joined March 2021</div>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <ProfileForm />
          )}
        </div>
      </div>
    </div>
  );
}

