import { Camera, Edit2, Check } from 'lucide-react';

interface ProfileHeaderProps {
  onEdit: () => void;
  isEditing: boolean;
}

export function ProfileHeader({ onEdit, isEditing }: ProfileHeaderProps) {
  return (
    <div className="relative bg-gradient-to-r from-violet-600 to-fuchsia-600 rounded-2xl h-36 overflow-hidden">
      {/* Cover art decoration */}
      <div className="absolute inset-0 opacity-20">
        <div className="absolute top-4 right-12 w-32 h-32 rounded-full bg-white/40 blur-2xl" />
        <div className="absolute -bottom-8 left-20 w-48 h-48 rounded-full bg-violet-900/40 blur-3xl" />
      </div>

      {/* Avatar */}
      <div className="absolute -bottom-10 left-6 group">
        <div className="w-20 h-20 rounded-2xl ring-4 ring-white bg-gradient-to-br from-violet-400 to-fuchsia-500 flex items-center justify-center text-white text-2xl font-bold shadow-lg">
          AL
        </div>
        <button className="absolute inset-0 flex items-center justify-center rounded-2xl bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity" aria-label="Change avatar">
