import { useState, FormEvent } from 'react';

export function ProfileForm() {
  const [saved, setSaved] = useState(false);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white rounded-2xl border border-slate-100 shadow-sm p-6 space-y-5 max-w-lg">
      <h3 className="font-semibold text-slate-800">Edit profile</h3>

      {[{ id: 'name', label: 'Full name', placeholder: 'Alice Langdon', defaultValue: 'Alice Langdon' },
        { id: 'handle', label: 'Username', placeholder: 'alice', defaultValue: 'alice' },
        { id: 'email', label: 'Email', placeholder: 'alice@acme.com', defaultValue: 'alice@acme.com' },
        { id: 'website', label: 'Website', placeholder: 'https://acme.design/alice', defaultValue: 'https://acme.design/alice' },
      ].map(f => (
        <div key={f.id}>
          <label htmlFor={f.id} className="block text-xs font-medium text-slate-600 mb-1.5">{f.label}</label>
          <input
            id={f.id}
            type="text"
            placeholder={f.placeholder}
            defaultValue={f.defaultValue}
            className="w-full h-9 px-3 text-sm rounded-lg border border-slate-200 focus:border-violet-400 focus:outline-none focus:ring-2 focus:ring-violet-100 transition-all"
          />
        </div>
      ))}

      <div>
        <label htmlFor="bio" className="block text-xs font-medium text-slate-600 mb-1.5">Bio</label>
        <textarea
          id="bio"
          rows={3}
          defaultValue="Senior product designer passionate about crafting elegant, accessible interfaces."
          className="w-full px-3 py-2 text-sm rounded-lg border border-slate-200 focus:border-violet-400 focus:outline-none focus:ring-2 focus:ring-violet-100 transition-all resize-none"
        />
      </div>

      <button
        type="submit"
        className={`px-5 py-2 rounded-lg text-sm font-semibold transition-all ${
          saved
            ? 'bg-emerald-500 text-white'
            : 'bg-violet-600 hover:bg-violet-500 text-white'
        }`}
      >
        {saved ? '✓ Saved!' : 'Save changes'}
      </button>
    </form>
  );
}
